<?php
require_once 'config.php';login_required();
if($_SERVER['REQUEST_METHOD']==='POST'){role_required(['admin','dosen']);$pdo->prepare("INSERT INTO jadwal(mata_kuliah_id,hari,mulai,selesai,ruangan) VALUES(?,?,?,?,?)")->execute([$_POST['mk'],$_POST['hari'],$_POST['mulai'],$_POST['selesai'],$_POST['ruangan']]);flash('Jadwal berhasil ditambahkan.');redirect('jadwal.php');}
$rows=$pdo->query("SELECT j.*,m.nama AS matkul,m.kode,u.nama AS dosen FROM jadwal j JOIN mata_kuliah m ON m.id=j.mata_kuliah_id LEFT JOIN users u ON u.id=m.dosen_id ORDER BY FIELD(hari,'Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'),mulai")->fetchAll();
$mks=$pdo->query("SELECT id,nama FROM mata_kuliah ORDER BY nama")->fetchAll();$page_title='Jadwal kuliah';require 'includes/header.php'; ?>
<div class="row g-4"><div class="col-lg-8"><div class="panel"><h3>Jadwal perkuliahan</h3><p class="muted">Pantau hari, jam, ruang, dan mata kuliah.</p><div class="table-responsive"><table class="table"><thead><tr><th>Hari</th><th>Waktu</th><th>Mata kuliah</th><th>Dosen</th><th>Ruang</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['hari']) ?></td><td><?= substr($r['mulai'],0,5) ?>–<?= substr($r['selesai'],0,5) ?></td><td><?= e($r['matkul']) ?><div class="muted small"><?= e($r['kode']) ?></div></td><td><?= e($r['dosen']??'-') ?></td><td><?= e($r['ruangan']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php if(in_array(user()['role'],['admin','dosen'])): ?><div class="col-lg-4"><div class="form-card"><h4>Tambah jadwal</h4><form method="post" class="d-grid gap-3"><select name="mk" class="form-select" required><option value="">Pilih mata kuliah</option><?php foreach($mks as $m): ?><option value="<?= $m['id'] ?>"><?= e($m['nama']) ?></option><?php endforeach; ?></select><select name="hari" class="form-select"><?php foreach(['Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'] as $h): ?><option><?= $h ?></option><?php endforeach; ?></select><input type="time" name="mulai" class="form-control" required><input type="time" name="selesai" class="form-control" required><input name="ruangan" class="form-control" placeholder="Ruang kelas" required><button class="btn btn-primary">Simpan jadwal</button></form></div></div><?php endif; ?></div>
<?php require 'includes/footer.php'; ?>